    ...base,
    id: `${base.id}${COPILOT_LONG_CONTEXT_ID_SUFFIX}`,
    requestModelId: base.id,
    name: `${base.name}${COPILOT_LONG_CONTEXT_NAME_SUFFIX}`,
    contextWindow: variantWindow,
