function githubCopilotModelManagerOptions(config3) {
  const rawApiKey = config3?.apiKey;
  const configuredBaseUrl = config3?.baseUrl ?? "https://api.githubcopilot.com";
  const parsedApiKey = rawApiKey ? parseGitHubCopilotApiKey(rawApiKey) : undefined;
  const apiKey = parsedApiKey?.accessToken;
  const baseUrl = parsedApiKey?.enterpriseUrl && configuredBaseUrl.includes("githubcopilot.com") ? getGitHubCopilotBaseUrl(parsedApiKey.enterpriseUrl) : configuredBaseUrl;
  const providerRefs = createBundledReferenceMap("github-copilot");
  const resolveReference = createReferenceResolver(providerRefs);
  return {
    providerId: "github-copilot",
    ...apiKey && {
      fetchDynamicModels: async () => {
        const longContextVariants = [];
        const models = await fetchOpenAICompatibleModels({
          api: "openai-completions",
          provider: "github-copilot",
          baseUrl,
          apiKey,
          headers: COPILOT_API_HEADERS,
          mapModel: (entry, defaults, _context) => {
            if (!isCopilotChatModel(entry)) {
              return null;
            }
            const reference = resolveReference(defaults.id);
            const copilotLimits = extractCopilotLimits(entry);
            const contextWindow = toPositiveNumber(copilotLimits.maxContextWindowTokens, toPositiveNumber(entry.context_length, toPositiveNumber(copilotLimits.maxPromptTokens, reference?.contextWindow ?? defaults.contextWindow)));
            const maxTokens = toPositiveNumber(copilotLimits.maxOutputTokens, toPositiveNumber(entry.max_completion_tokens, toPositiveNumber(copilotLimits.maxNonStreamingOutputTokens, reference?.maxTokens ?? defaults.maxTokens)));
            const name = typeof entry.name === "string" && entry.name.trim().length > 0 ? entry.name : reference?.name ?? defaults.name;
            const api3 = inferCopilotApi(defaults.id);
            const supportsVision = extractCopilotSupportsVision(entry);
            const input2 = supportsVision ? ["text", "image"] : reference?.input ?? defaults.input;
            const tokenPrices = extractCopilotTokenPrices(entry);
            const defaultContextMax = tokenPrices.defaultTier?.contextMax;
            const defaultTierWindow = defaultContextMax !== undefined && defaultContextMax > 0 ? Math.min(contextWindow, defaultContextMax + maxTokens) : contextWindow;
            const base = reference ? {
              ...reference,
              api: api3,
              provider: "github-copilot",
              baseUrl,
              name,
              input: input2,
              contextWindow: defaultTierWindow,
              maxTokens,
              headers: { ...COPILOT_API_HEADERS, ...providerRefs.get(defaults.id)?.headers ?? {} },
              ...api3 === "openai-completions" ? {
                compat: {
                  supportsStore: false,
                  supportsDeveloperRole: false,
                  supportsReasoningEffort: false
                }
              } : {}
            } : {
              ...defaults,
              api: api3,
              baseUrl,
              name,
              input: input2,
              contextWindow: defaultTierWindow,
              maxTokens,
              headers: { ...COPILOT_API_HEADERS },
              ...api3 === "openai-completions" ? {
                compat: {
                  supportsStore: false,
                  supportsDeveloperRole: false,
                  supportsReasoningEffort: false
                }
              } : {}
            };
            const variant = createCopilotLongContextVariant(base, contextWindow, maxTokens, tokenPrices.longContext);
            if (variant) {
              longContextVariants.push(variant);
              base.contextPromotionTarget ??= `github-copilot/${variant.id}`;
            }
            return base;
          },
          fetch: config3?.fetch
        });
        if (models === null) {
          return null;
        }
        const takenIds = new Set(models.map((model) => model.id));
        for (const variant of longContextVariants) {
          if (takenIds.has(variant.id)) {
            continue;
          }
          takenIds.add(variant.id);
          models.push(variant);
        }
        return models.sort((left, right) => left.id.localeCompare(right.id));
      }
    }
  };
}
